		{ key = "comboColour", kind = "colour", default = "ffe8452e", label = "Combo point colour", needs = "comboPoints",
			tip = "The colour of a lit point; the points you do not have yet show in it faintly." },
		{ key = "comboFull", kind = "bool", default = true, label = "Full points stand out", needs = "comboPoints",
			tip = "At your most points every square takes Full points colour and the row pops once." },
		{ key = "comboFullColour", kind = "colour", default = "ffffd100", label = "Full points colour", needs = "comboFull",
			tip = "The colour of every point while you sit at your most points." },
		{ key = "comboBreathe", kind = "bool", default = true, label = "Full points breathe", needs = "comboFull",
			tip = "While you sit at your most points the row breathes softly until you spend them." },
		{ key = "comboSize", kind = "number", default = 7, min = 4, max = 16, step = 1, label = "Combo point size", needs = "comboPoints",
			tip = "The size of each combo point square." },
		{ key = "comboY", kind = "number", default = 0, min = -20, max = 20, step = 1, label = "Combo points vertical offset", needs = "comboPoints",
			tip = "Moves the row up or down, and a Below threat value with it." },
		{ section = "Quest" },
		{ key = "questMark", kind = "bool", default = true, label = "Quest mark on enemies you need for a quest",
