		{ key = "questMarkSize", kind = "number", default = 14, min = 8, max = 32, step = 1, label = "Quest mark size", needs = "questMark",
			tip = "The size of the quest mark, and of its kill count with it." },
		{ key = "questMarkCount", kind = "bool", default = true, label = "Kill count beside the quest mark", needs = "questMark",
			tip = "How many of that enemy you have slain and need, such as 3/8. It turns green at 8/8 as the objective completes, then the mark fades. Enemies that drop a quest item have no count." },
		{ key = "questMarkPlace", kind = "choice", default = "left", label = "Quest mark position", needs = "questMark",
			tip = "Left goes past the threat value, the enemy's buffs, the raid marker and the elite or rare icon. Right goes past the threat texts and the enemy's crowd control icons. Above sits over the enemy's debuffs, an Above threat value and the Overpower icon.",
			choices = { { "left", "Left" }, { "right", "Right" }, { "above", "Above" } } },
		{ key = "questMarkX", kind = "number", default = 0, min = -40, max = 40, step = 1, label = "Quest mark horizontal offset", needs = "questMark",
			tip = "Moves the quest mark and its kill count left or right." },
		{ key = "questMarkY", kind = "number", default = 0, min = -40, max = 40, step = 1, label = "Quest mark vertical offset", needs = "questMark",
			tip = "Moves the quest mark and its kill count up or down." },
		{ key = "questMarkQuestie", kind = "bool", default = true, label = "Leave quest marks to Questie", needs = "questMark",
