		{ key = "thrownMin", kind = "number", default = 20, min = 0, max = 200, step = 5, label = "Thrown weapon minimum",
			tip = "With a thrown weapon, the ammunition tracker is low at this many or fewer. 0 means never. One that wears out is low at a fifth of its durability." },
		{ key = "durabilityMin", kind = "number", default = 20, min = 0, max = 100, step = 5, unit = "%", label = "Durability minimum",
			tip = "The durability tracker is low when an item you wear is at this much of its durability or less, and red when one is broken. 0 means never. At a ready check or pull countdown, until the pull, it is also low at 40% or less, and shows when low or broken, whatever Show says, while Show at a ready check or pull countdown is on." },
		{ section = "Pet" },
		{ key = "petHealthMin", kind = "number", default = 30, min = 0, max = 90, step = 5, unit = "%", label = "Pet health minimum",
