	{
		key = "threat", label = "Threat list",
		{ key = "enabled", kind = "bool", default = true, label = "Show the threat list",
			tip = "Your group by threat on the enemy you fight, highest first: 100% has aggro or takes it. While you are a tank the other enemies you are losing show under it, and List can show only the enemies you fight instead. /flatui move places the list, /flatui threat shows a sample." },
		{ section = "When it shows" },
		{ key = "show", kind = "choice", default = "group", label = "Show", tip = "Only in a fight, while your target, the target of your target or, with Follow your tank's target, your tank's target is an enemy, or while you are a tank, an enemy you are losing.",
			choices = { { "group", "In a group" }, { "instance", "In a dungeon or raid" }, { "always", "In a group or alone" } } },
		{ key = "view", kind = "choice", default = "both", label = "List",
			tip = "Your target, then enemies you are losing, the default, shows your group on your target, and while you are a tank (your group role, else your stance or form, or Your role of nameplate threat) adds under a thin line up to 4 small rows for the other enemies that are Lost or Slipping, the lost ones first; nothing more while none is. With no enemy as your target, your target's target or your tank's target, a tank's list shows the group on the enemy you are losing most, the others still under it. Enemies you fight has a row for each enemy with a nameplate that fights you or your group instead, the ones you are losing first, in every role. Your group on your target shows the group alone.",
			choices = { { "both", "Your target, then enemies you are losing" }, { "mobs", "Enemies you fight" }, { "group", "Your group on your target" } } },
		{ key = "follow", kind = "bool", default = true, label = "Follow your tank's target",
			tip = "With no enemy as your target or your target's target, the list shows the enemy your group's tank fights (their tank role, the raid's main tank, or in a party their tank stance, form or aura), and the title names the tank: for a healer who heals without a target." },
		{ section = "Bars" },
