	},
	{
		key = "windowsItems", label = "Item slots", owner = "windows",
		{ section = "Item slots" },
		{ key = "slots", kind = "bool", default = true, label = "Flat item slots", reload = "off", tip = RELOAD },
		{ key = "quality", kind = "bool", default = true, label = "Quality colour", tip = "Colours the slot border by item quality.", needs = "slots" },
		{ key = "slotTints", kind = "bool", default = true, label = "Flat highlights", reload = "off", tip = RELOAD, needs = "slots" },
		{ key = "qualityMin", kind = "choice", default = "all", label = "Quality border from", needs = "quality",
			choices = { { "all", "Every item" }, { "uncommon", "Green and better" }, { "rare", "Blue and better" }, { "epic", "Epic and better" } } },
		{ key = "countSize", kind = "number", default = 115, min = 50, max = 250, step = 5, unit = "%", label = "Stack count size" },
		{ section = "Item level" },
		{ key = "ilvlBags", kind = "bool", default = true, label = "Item level in bags and bank",
			tip = "In the game's bag and bank windows. The Bags page has its own." },
		{ key = "ilvlCharacter", kind = "bool", default = true, label = "Item level on equipped gear" },
		{ key = "ilvlFlyout", kind = "bool", default = true, label = "Item level in the equipment flyout", needs = "ilvlCharacter",
			tip = "The bag items that fit a slot of the Character window, shown while you hold Alt over the slot." },
		{ key = "ilvlInspect", kind = "bool", default = true, label = "Item level on the Inspect window",
			tip = "On each slot, and the player's average item level under their level." },
		{ key = "ilvlCorner", kind = "choice", default = "bottomLeft", label = "Item level corner on gear",
			tip = "On the slots of the Character and Inspect windows. Bags and the flyout keep the bottom left.",
			choices = { { "bottomLeft", "Bottom left" }, { "bottomRight", "Bottom right" }, { "topLeft", "Top left" }, { "topRight", "Top right" } } },
		{ key = "ilvlSize", kind = "number", default = 15, min = 8, max = 18, step = 1, label = "Item level size" },
		{ key = "ilvlColour", kind = "choice", default = "quality", label = "Item level colour",
			choices = { { "quality", "Item quality colour" }, { "white", "White" }, { "gold", "Gold" } } },
		{ section = "The game's bag windows" },
		{ key = "newGlow", kind = "bool", default = true, label = "New item glow", tip = "In the game's bag windows. The Bags page has its own." },
		{ key = "junkDim", kind = "bool", default = true, label = "Dim grey items", tip = "Darkens poor items that have a vendor price, in the game's bag and bank windows." },
		{ key = "boeMark", kind = "bool", default = true, label = "Mark bind on equip items",
			tip = "BoE at the top left of an item that binds when equipped and is not bound yet, in the game's bag and bank windows. The Bags page has its own marks." },
		{ key = "unusableTint", kind = "bool", default = true, label = "Tint items you cannot use", tip = "Red over an item whose tooltip has a requirement in red: class, race, level, skill, reputation, armour or weapon type, or a recipe you already know. In the game's bag and bank windows." },
		{ key = "petFood", kind = "bool", default = true, label = "Mark food your pet eats", tip = "For hunters: the Feed Pet icon at the bottom left of food your pet eats, while it is out. In the game's bag and bank windows." },
		{ key = "combinedBags", kind = "bool", default = false, cvar = "combinedBags", label = "Combine bags" },
		{ key = "bagKey", kind = "bool", default = true, label = "Backpack key opens every bag", changed = "BagKeyChanged",
			tip = "B, or your key for Toggle Backpack, opens the reagent bag with your other bags and closes them all again, as Open All Bags (Shift+B) does. With separate bags it opens all of them, not only the backpack." },
		{ section = "Clean up bags" },
		{ key = "sortButton", kind = "choice", default = "title", label = "Clean up bags button", tip = "Under the slots, only the lowest bag of a stack has a button. /flatui sort and the key Flat UI bags: clean up, under Flat UI in Key Bindings, clean up your bags too; the key also works while only the Bags page is on, waits while a clean up still runs, and the sort button of Flat UI's bag window names it.",
			choices = { { "title", "In the title bar" }, { "slots", "Under the slots" }, { "none", "None" } } },
		{ key = "sortBank", kind = "bool", default = true, label = "Also on the bank", needs = "sortButton", needsIn = { "title", "slots" } },
		{ key = "sortFrom", kind = "choice", default = "other", label = "Items gather", tip = "Also applies to the game's own clean up.",
			choices = { { "game", "As the game sorts" }, { "other", "From the other end" } } },
		{ section = "Character window" },
		{ key = "durability", kind = "bool", default = true, label = "Show durability",
			tip = "Of all the gear you wear, under the left column of slots: white above 80%, yellow above 50%, red at 50% and below, and red while an item is broken, yellow while one is at 20% or less. Point at it for each item with its icon, lowest first, and about what a repair costs. Not where gear does not wear out." },
		{ key = "durabilitySlots", kind = "choice", default = "worn", label = "Durability on each slot", needs = "durability",
			tip = "A small percent in the top corner of each slot of the Character window whose item has worn: yellow, then red at 20% or less and when broken. The corner is opposite Item level corner on gear when that is at the top.",
			choices = { { "worn", "At 50% or less" }, { "always", "Always under 100%" }, { "off", "Off" } } },
		{ key = "thorns", kind = "bool", default = true, label = "Show thorns",
			tip = "The damage an attacker takes each time it strikes you in melee, one total under the right column of slots: Thorns, Retribution Aura, Fire Shield, items and shield spikes (on a block). Point at it for each source and school. It shows only while something deals such damage." },
		{ key = "thornsZero", kind = "bool", default = false, label = "Also at 0", needs = "thorns",
			tip = "Shows Thorns 0 in grey while nothing deals damage to attackers." },
		{ key = "statTips", kind = "bool", default = true, label = "Explain the stats", changed = "StatTipsChanged",
			tip = "Point at a stat on the Character window for a few plain lines under the game's own, in your numbers now: what it does for you, against an enemy of your level and a boss three levels above (from level 60, or as Against on the Gear comparison page names one), and what to aim for. Defense shows what 100 melee swings of each do to you (missed, dodged, parried, blocked, crits, crushing blows and normal hits) and how far you are from 440 defense, for no crits from a raid boss, and from 100% avoided, for no crushing blows. Block says how much one block stops and where it comes from; armor and resistances what share of the damage they take off. In a fight, the numbers from before it." },
	},
	{
		key = "bags", label = "Bags",
		{ key = "enabled", kind = "bool", default = true, label = "Flat UI bags",
			tip = "One window for all your bags, with sections, a search and your gold, and one for your bank, which also shows it away from the banker. The name in either window's title picks another of your characters, to see their bags or bank. Point at the gold under the bag window for every character's gold, this one marked in your accent colour, and what you made this session and since when, an hour too after ten minutes, and Ctrl-click it to count the session from now. The game's bag windows stay hidden while it is on, and its bank window too while At the banker is Flat UI's. It stays off while another bag addon is loaded, and under the gamepad interface. /flatui bags and /flatui bank open them." },
		{ section = "Window" },
		{ key = "view", kind = "choice", default = "sections", label = "Show items",
			tip = "Sections groups items by kind. Bag by bag shows each bag in turn, as the game does, under its icon, name and free slots; bags with the same name add their number (bag 3); click or right-click a label for that bag's settings. The button in the window's title switches between them.",
			choices = { { "sections", "Sections" }, { "bags", "Bag by bag" } } },
		{ key = "columns", kind = "number", default = 12, min = 6, max = 30, step = 1, label = "Width in slots",
			tip = "At most as many as fit on your screen. Or drag the window's free corner, its bottom left, one column at a time, up to what fits; double-click it for 12 again." },
		{ key = "bankColumns", kind = "number", default = 16, min = 6, max = 36, step = 1, label = "Bank width in slots",
			tip = "At most as many as fit on your screen. Or drag the window's free corner, its bottom right, one column at a time, up to what fits; double-click it for 16 again." },
		{ key = "slotSize", kind = "number", default = 36, min = 24, max = 48, step = 2, unit = " px", label = "Slot size" },
		{ key = "freeSlots", kind = "choice", default = "kinds", label = "Free slots", needs = "view", needsIn = { "sections" },
			tip = "Only the backpack and normal bags count as free space, here and under the window: trade bags, quivers, ammo pouches, soul bags, the reagent bag and the keyring take only certain items. One per kind shows a slot with the number free in normal bags and, in your own bags, one for each kind of special bag with room, not counted in the title. Drop an item on it to put it there. Bag by bag shows each bag's free slots on its label.",
			choices = { { "kinds", "One per kind of bag" }, { "all", "Every free slot" } } },
		{ key = "bagSlots", kind = "bool", default = true, label = "Bag slots",
			tip = "A row over the bag window's footer with your backpack, bags and reagent bag, and your keyring at the end while the game shows one, also while the game's bag bar is hidden or faded away, under a thin line apart from your items. Each bag shows its free slots in its corner, gold at 4 or fewer and red when it is full, and the keyring how many keys it holds (point at it to see them by name). Drag a bag from your bags onto a slot to put it in or swap it, drag a slot to take its bag out, and point at one to see that bag's free slots and light its items in the window; its tooltip opens beside the window, so the lit items stay in view. While a spare bag is in your bags, each empty slot it fits stays lit, and a click there puts it in, largest first. Drop a key on the keyring, or click it with a key, to put the key on your keyring. Click a bag to show only that bag, its edge lit, until you click it again, take it out or close the window, and right-click it for its settings (Assign To, Ignore Clean Up and Junk Selling), which its tooltip names. A slot glows while the bag on your cursor fits it and greys while its own bag is lifted, and loot you get pops on the slot of the bag it goes into. Putting in and taking out bags, and keys, waits for the end of a fight." },
		{ key = "currencies", kind = "bool", default = true, label = "Currencies in the footer",
			tip = "Shows what the Currency tab of the Character window marks Show on Backpack, after your gold under the bag window, in the game's order: each currency's icon with how many you have. Point at one for its tooltip, and click it to open the Currency tab (in a fight, once it ends). Shift-click it to link it in chat, or, with no chat box open, to take it off the footer, as on the game's backpack. Another character's bags show its currencies as Flat UI last saw them. When the window is too narrow for them all, the last ones lose their counts first." },
		{ key = "fullSay", kind = "bool", default = true, label = "Say when your bags fill",
			tip = "Says once in chat the moment the last free slot of your backpack and normal bags fills, also with the bag window closed: Flat UI: your bags are full (0 of 80 free). Special bags, such as quivers, ammo pouches, soul bags, trade bags and the keyring, do not count. It says it again only after a slot frees up, and at most once in 10 seconds, so looting and selling never fill your chat." },
		{ key = "fullSound", kind = "choice", default = "none", label = "Sound when your bags fill", needs = "fullSay", changed = "BagsFullSoundPicked",
			tip = "Plays with the line in chat. Out of combat, a pick plays it.",
			choices = { { "none", "None" }, { "bell", "Bell" }, { "chimes", "Chimes" }, { "alarm", "Alarm" }, { "raid", "Raid warning" } } },
		{ section = "Sections" },
		{ key = "newItems", kind = "bool", default = true, label = "New items at the top",
			tip = "Items the game marks as new stay at the top until you close the bags after seeing them; a click on the title there, or a clean up, puts them away now. Anything else that comes into your bags while they are open, such as an item from the bank, gear you take off or an item moved to an empty slot, waits there too, and with this row off so does everything: the shelf is titled New items only while everything on it is new, else Added. Point at its title for what came in, each item with its count, and what it is worth at a merchant. An item you placed in a section by hand (Items placed by hand) goes straight to that section instead, glowing while it is new." },
		{ key = "gear", kind = "choice", default = "one", label = "Equipment",
			tip = "In Sections. Weapons, armour and jewellery puts shields, off-hands and relics with the weapons. Each kind shows Weapons (bows, guns, wands and thrown weapons too), Shields and off-hands, Armour, Rings, Necklaces, Trinkets, Relics, and Shirts and tabards, with Equipment for anything else you can equip. Each can be folded, moved, deleted and dropped on like any other section, and right-clicking one of their titles changes this row too; Delete a section below deletes the whole group at once.",
			choices = { { "one", "One section" }, { "kind", "Weapons, armour and jewellery" }, { "each", "Each kind" } } },
		{ key = "addSlots", kind = "bool", default = true, label = "Drop slot in each section",
			tip = "In Sections, each section of your bags ends in an empty slot with a +. Drop an item on it, or click it with an item on your cursor, to keep that item in that section: on Junk it goes on your sell list, on Keep in place its slot is pinned. An item from your bank or one you wear goes into a free slot of your bags first, out of combat, and a merchant's item is bought into one, unless the game asks before it buys that item; nothing moves when the section would not take the item, such as a quest item on Junk. A drop on a section's title, or anywhere among its slots, does the same, in both windows and with this row off too, while a drop on an item swaps the two as before. While an item or a merchant's item is on your cursor, every + slot and title that would take it lights in your Highlight colour, and one that would not stays unlit, its tooltip saying why in red; nothing lights in a fight. The + slots draw on Free slots, whose title says how many are free of how many (gold at 4 or fewer, red at none): with no free slot left they dim, and still take an item that is already in your bags." },
		{ key = "consumables", kind = "choice", default = "one", label = "Consumables",
			tip = "In Sections. Food, potions and the rest shows Food and drink, Potions and elixirs (flasks too) and Consumables for the rest, such as bandages and scrolls. Each kind shows Food and drink, Potions, Elixirs and flasks, Scrolls, Bandages, Enhancements (weapon oils, sharpening stones and the like), and Explosives and devices, which the game counts as trade goods but go here then, with Consumables for the rest. Each can be folded, moved, deleted and dropped on like any other section, and right-clicking one of their titles changes this row too; Delete a section below deletes the whole group at once.",
			choices = { { "one", "One section" }, { "kind", "Food, potions and the rest" }, { "each", "Each kind" } } },
		{ key = "tradeGoods", kind = "choice", default = "one", label = "Trade goods",
			tip = "In Sections. Each kind shows Cloth, Leather, Metal and stone, Herbs, Elemental, Enchanting, Meat and Parts (with explosives and devices, unless Consumables is at Each kind), with Trade goods for the rest, such as gems. Each can be folded, moved, deleted and dropped on like any other section; right-click one of their titles to split them or join them into one again, and Delete a section below deletes the whole group at once.",
			choices = { { "one", "One section" }, { "each", "Each kind" } } },
		{ key = "itemOrder", kind = "choice", default = "kind", label = "Order in a section", needs = "view", needsIn = { "sections" },
			tip = "How the items of each section line up, in both windows and for all your characters. By kind puts gear by slot and item level and the rest by kind, then quality, name and stack size; the others put their own order first and then that one. Keep in place keeps the order of your bags, and Bag by bag is the game's order.",
			choices = { { "kind", "By kind" }, { "quality", "Best quality first" }, { "name", "By name" }, { "level", "Highest item level first" } } },
		{ key = "placed", kind = "list", default = 0, label = "Items placed by hand", none = "Choose one to put it back in its own section", items = "BagsPlacedLines",
			pick = "BagsPlacedPick",
			tip = "In Sections, drop an item from your bags on the title of a section, its + slot or among its slots to keep it there: from then on every stack of it shows in that section, in the bag and bank windows and for all your characters, also when you loot it again (it still glows while it is new) or move it while the bags are open, until you place it somewhere else or put it back here. A drop on the section it would go to anyway keeps it there too, so changing Equipment, Consumables or Trade goods, or a section deleted and brought back, never moves it; one placed in a kind the row does not show now, such as Potions with Consumables as one section, shows in the section that holds that kind and in Potions again once the row shows it. Dropped on Junk, whose title is always there unless you delete it, it goes on your sell list (/flatui sell); an item of Junk or a grey one dropped on another section comes off the sell list, and a grey one goes on your keep list (/flatui keep), while Junk is not deleted. An item you put on your sell list another way shows in Junk while it is there, as Sell junk sells it, and in its section again once it comes off; in a pinned slot it shows in Keep in place. In the bag and bank windows such an item's tooltip ends with Placed by hand in that section. Choose an item here to put it back in its own section, or, with two or more placed, the first line to put them all back, or right-click a section's title to put back the items placed there. Until the next put back or a reload, that title's menu and the first line here bring back what the last one took away, each item in the section it was in, unless it is placed elsewhere since. With a search typed, a section's right-click menu also places there every item the search finds in other sections (Place the 7 items that match the search here), New items too but not those of Junk or Keep in place, so #boe q>=uncommon fills an Auction section at once; #placed finds every item you placed. At most 2000 items are placed by hand." },
		{ key = "order", kind = "list", default = 0, label = "Section order", none = "Choose one", items = "BagsOrderLines", pick = "BagsOrderPick",
			tip = "In Sections, drag a section's title to move the section, or right-click the title to move it up, down, to the top or to the bottom. One order for both windows and all your characters; New items stays at the top and Free slots at the bottom. This puts Flat UI's own order back." },
		{ key = "folded", kind = "list", default = 0, label = "Folded sections", none = "Choose one to open it", items = "BagsFoldLines", pick = "BagsFoldPick",
			tip = "In Sections, click a section's title to fold it to its title and count, and click again to open it; Shift-click it to open only that section and fold the others, and Shift-click it again to open them all. Its right-click menu folds and opens it, or every section. The same sections fold in both windows and for all your characters. Point at a folded title to see what it holds, each item with its count. While you search, every section's title says how many of its items match, as in 3 of 24, and a section with no match fades. This opens one folded section, or all of them; a fold kept for a deleted section is marked (deleted), and one for a section not shown now, such as Rings with Equipment at One section, (not in use now)." },
		{ key = "remove", kind = "list", default = 0, label = "Delete a section", none = "Choose one to delete it", items = "BagsRemoveLines",
			pick = "BagsRemovePick",
			tip = "In Sections, deletes a section in both windows and for all your characters, as Delete this section in its title's right-click menu does. It lists every section you can delete now, in the order the windows show them: Flat UI's own, and yours, marked (yours). While Equipment, Consumables or Trade goods shows its kinds apart, a line before them deletes the whole group at once (Equipment: all 8 kinds), and it stays deleted if you change that row later; the group's own section, which holds the rest, is marked (the rest). A deleted section's items go to the next section that takes them, so nothing is lost: Other is not listed, since it takes whatever no other section does. Deleting Junk only moves your junk into other sections (Sell junk, the junk coin and your sell list stay), and deleting Keep in place leaves your pins as they are. Deleted sections below brings one of Flat UI's back; one of yours goes with its items put back in their own sections, and until the next delete or a reload Bring back in Custom sections, or at the top of + New section's menu, restores it. New items and Free slots are not listed: they are shelves, not sections, and no row turns them off (with New items at the top off nothing is kept as new, but the shelf still holds what comes in while the bags are open)." },
		{ key = "hidden", kind = "list", default = 0, label = "Deleted sections", none = "Choose one to bring it back", items = "BagsHiddenLines",
			pick = "BagsHiddenPick",
			tip = "In Sections, right-click a section's title and choose Delete this section, or choose it in Delete a section, to delete it in both windows and for all your characters: every section of Flat UI's own but New items, Free slots and Other can be deleted and brought back here, while a section of your own you delete comes back from Custom sections instead, which brings back the last one. Its items go to the next section that takes them: a deleted kind of Equipment, Consumables or Trade goods sends them to the rest of its group while that shows (a deleted Potions to Consumables, Rings to Equipment, Weapons to Armour at Weapons, armour and jewellery), else on to the next section that takes them, and Other takes what is left, so nothing is lost. Deleting Junk only moves your junk into other sections: Sell junk, the junk coin and your sell list stay as they are, also when you drop junk on another section. Deleting Keep in place leaves your pins as they are, also when you drop a pinned item on another section, and shows those items by kind. Items you placed by hand in a deleted section come back to it when you bring it back, and so do its place and its fold. Deleted (3) after the last section names them in its tooltip and opens a list to bring one back, which says so in chat and flashes the section that comes back. Choose one here to bring it back, which flashes Back on it in the bag window too, or, with two or more deleted, the first line to bring them all back; one the rows do not show now, such as Jewellery with Equipment at Each kind, is marked (not in use now)." },
		{ key = "custom", kind = "list", default = 0, label = "Custom sections", none = "Choose one", items = "BagsCustomLines", pick = "BagsCustomPick",
			tip = "Sections of your own, with names you choose, at most 20. Click + New section after the last section in the bag window, choose New section from a section title's right-click menu, or choose Make a new section here, then type a name of up to 24 letters and press Enter (Escape cancels); drop an item on + New section to make one for that item, its kind (such as Mail) already typed in. Drop items on a section's title, its + slot or among its slots to keep them there, and right-click its title to rename it, give it a colour (its title and + take it; Flat UI's own sections take a colour from their title's menu too), empty it or delete it, or right-click + New section for all of yours. Deleting one puts its items back in their own sections; until the next delete or a reload, Bring back, first in + New section's menu and here, restores it with its items, its fold and its place. With a search typed, Keep what the search finds here in a section's title menu makes it keep every item that search finds from then on, also items looted later, in both windows and for all your characters (after items placed by hand, New items, Junk and Keep in place); its title's tooltip names the search, and the same menu stops it, searches for it again or, with another search typed, keeps that one instead (it names the one it replaces). Here, Stop keeping what it finds, under each such section, stops it too. Your sections are the same in both windows and for all your characters, come after Keep in place, move with Section order, fold with a click, and the search finds them by name." },
		{ section = "Pinned slots" },
		{ key = "pinMoves", kind = "bool", default = true, label = "Put pinned items back",
			tip = "Ctrl+right-click an item in your bags to pin its slot to it, and again to unpin it; Ctrl+left-click stays the dressing room. A pinned slot has a small square at its top right, its item's tooltip says it is pinned, and in Sections its items are in Keep in place, in the order of your bags and never sorted, with an empty pinned slot shown faded. Drop an item on Keep in place's title to pin its slot, or a pinned item on another section to unpin it (not while Keep in place is deleted). If Ctrl is your Auto Loot Key, Ctrl+right-click opens an item that holds loot instead, so drop that one on Keep in place. A pinned item comes off your sell list, and a grey one goes on your keep list, so it is never sold as junk; unpinning leaves both lists as they are. With this on, Flat UI puts each pinned item back in its slot after a clean up of your bags, and when that item comes into your bags while its slot holds something else or nothing, out of combat; a move inside your bags is left as you made it until then. A bag set to ignore clean up gets no other item. The game's clean up cannot leave single items alone, so they leave and come back, and the sort button stays busy until they are back. Right-click Keep in place's title to put them back now." },
		{ key = "pins", kind = "list", default = 0, label = "Pinned slots", none = "Choose one to unpin it", items = "BagsPinLines", pick = "BagsPinPick",
			tip = "This character's pinned slots, by bag and slot. Pins are kept per character, at most 100, in your bags only: not the keyring, the bank or another character's bags." },
		{ section = "Slots" },
		{ key = "itemLevel", kind = "bool", default = true, label = "Item level",
			tip = "On weapons and armour, in the colour of the item's quality, and on bags and quivers, how many slots they have, in grey." },
		{ key = "quality", kind = "choice", default = "all", label = "Quality border",
			choices = { { "all", "Every item" }, { "uncommon", "Green and better" }, { "rare", "Blue and better" }, { "epic", "Epic and better" }, { "off", "Off" } } },
		{ key = "marks", kind = "bool", default = true, label = "Item marks",
			tip = "BoE at the top left of items that bind when equipped, but not on one with the junk coin, which takes that corner; red over items you cannot use; the Feed Pet icon on food your pet eats; a green plus at the bottom left of a recipe you can learn now (search #learnable to light them all); and a small gold open at the bottom left of an item you can open, such as a clam, a satchel or a lockbox once it is picked (search #openable to light them all)." },
		{ key = "junkCoin", kind = "bool", default = true, label = "Junk coin",
			tip = "The game's coin at the top left of what Sell junk would sell, as Errands sells. It stays while the game holds the item for a moment, as in a trade, on a mail not sent yet or on the cursor, though Sell junk leaves it until then. Alt+right-click an item in the bag window to put it on your sell list, and again to take it off (a grey one then goes on your keep list); quest items, items with no sell price and pinned items stay off it. Right-click the Junk title for Your sell list and Never sold, to take an item off either list, also one no longer in your bags." },
		{ key = "newGlow", kind = "bool", default = true, label = "New item glow", tip = "The game's glow on a new item, until you point at it." },
		{ section = "Bank" },
		{ key = "bank", kind = "choice", default = "flat", label = "At the banker",
			tip = "Flat UI's bank window is live at the banker, with Deposit and Take out, and shows your bank anywhere else. While it is open, windows that open on the left, such as the Character window, open one place further right. With the game's bank window, Flat UI's shows your bank as last seen, also at the banker, with no clicks, Deposit or Take out. A change counts from your next visit to a banker.",
			choices = { { "flat", "Flat UI's bank window" }, { "game", "The game's bank window" } } },
		{ key = "openWithBank", kind = "bool", default = true, label = "Open the bags at the banker", needs = "bank", needsIn = { "flat" },
			tip = "Your bags open with Flat UI's bank window." },
		{ key = "bankButtons", kind = "bool", default = true, label = "Deposit and Take out", needs = "bank", needsIn = { "flat" },
			tip = "Buttons on the bank window that move every item matching the search, one at a time, out of combat. At the banker a section's right-click menu also puts the whole section in the bank, or takes it out in the bank window, with no search; with this off it does neither. The line in chat after a pass follows Say what was done on the Errands page, which changes only while Errands is on." },
		{ section = "Merchant and trade" },
		{ key = "sellButton", kind = "bool", default = true, label = "Sell junk button",
			tip = "At a merchant, under the bag window: sells every item with the junk coin, as Errands sells, also with Errands off. That is grey items with a price, except in a bag you leave out of junk selling, and the items of your sell list (/flatui sell). Its tooltip says what they bring and lists them by name, the one that brings the most first, each with its count and what it brings (12 lines, then and 3 more; ? where the game has not said yet), and while you point at it every other item in the bag window dims, and so do the titles of sections with nothing to sell, so only what it would sell stays lit; the Junk title's tooltip says what your junk is worth and lists it the same way, open or folded. While it sells, its label and tooltip count down what is left. With Sell at most 12 at a time on, the items of your sell list that are not grey go 12 per click. That row and Say what was done, for the line in chat after a sale, are on the Errands page and change only while Errands is on, the first with Sell grey items on too." },
		{ key = "openWithTrade", kind = "bool", default = true, label = "Open the bags for a trade",
			tip = "The game itself opens them for a trade only under the gamepad interface." },
		{ section = "Other characters" },
		{ key = "altCounts", kind = "bool", default = true, label = "Counts in tooltips",
			tip = "An item's tooltip names your other characters on this realm and its connected realms who carry it, in their bags, bank or gear, as Flat UI last saw them. When this character's bank holds some, or it wears one, a first line in your class colour says how many you have in your bags, your bank and your gear, and with anyone else listed the last line, In all, adds them all up." },
		{ key = "forget", kind = "list", default = 0, label = "Forget a character", none = "Choose a character", items = "BagsCharacterLines",
			pick = "BagsCharacterForget", tip = "Takes a character's bags, bank and gold out of Flat UI's records. It is kept again when it logs in with Flat UI bags on." },
	},
