		{ key = "trackerQuestie", kind = "bool", default = true, label = "Questie's tracker",
			tip = "Gives the quest tracker of the Questie addon the look of the rows above: background, headings, Heading size on its zone headings, item buttons and Opacity in combat, and the fonts of the Fonts page while that page is on. Needs Questie: without it this row does nothing. Off gives Questie its own look back." },
		{ section = "Loot" },
		{ key = "lootWindow", kind = "bool", default = true, label = "Loot window", tip = "Flat window with thin borders on the window, the cards and the item slots." },
		{ key = "lootRolls", kind = "bool", default = true, label = "Loot rolls",
			tip = "Flat background and thin border on each roll, the icon cropped with a border in the item's quality colour, a flat timer bar, and Need, Greed and Pass in a row. Off gives the rolls the game's look back. /flatui move moves the rolls, on or off." },
		{ key = "lootRollTime", kind = "bool", default = true, label = "Seconds left on rolls", needs = "lootRolls",
			tip = "The seconds left to roll, at the right end of the timer, in red with the bar under 10 seconds." },
		{ key = "lootRollSound", kind = "choice", default = "none", label = "Sound before a roll ends", needs = "lootRollTime", changed = "LootRollSoundPicked",
			tip = "Plays once when a roll you have not rolled on has 5 seconds left. Picking one plays it.",
			choices = { { "none", "None" }, { "spell", "Spell alert" }, { "chimes", "Chimes" }, { "bell", "Bell" }, { "warhorn", "Warhorn" },
				{ "raid", "Raid warning" }, { "alarm", "Alarm" }, { "whisper", "Whisper warning" } } },
		{ key = "lootRollsGrow", kind = "choice", default = "up", label = "Rolls stack", choices = { { "up", "Up" }, { "down", "Down" } },
			tip = "Which way more rolls stack from the spot you gave Loot rolls in /flatui move: Up, as the game stacks them, or Down. Until you move them the game places the rolls." },
		{ key = "lootQualityText", kind = "bool", default = true, label = "Quality word on loot", needs = "lootWindow" },
		{ section = "Alerts" },
		{ key = "alerts", kind = "bool", default = true, label = "Loot, money and honour alerts", tip = "Flat background with a thin border." },
	},
	{
		key = "hudMessages", label = "Messages and timers", owner = "hud",
		{ section = "Error messages" },
		{ key = "errors", kind = "bool", default = true, label = "Hide error messages",
			tip = "Only the kinds below that are on, with their sound and voice. Other red errors and the yellow quest messages show as usual, even while a macro or addon turns the game's error text off with UIErrorsFrame:UnregisterEvent." },
		{ key = "errorsWhen", kind = "choice", default = "always", label = "When", needs = "errors",
			choices = { { "always", "Always" }, { "combat", "Only in a fight" } },
			tip = "Only in a fight shows every message out of combat, so you still learn why a mailbox or a cast on a mob failed." },
		{ key = "errorTextSize", kind = "number", default = 100, min = 50, max = 150, step = 5, unit = "%", label = "Error text size", changed = "ErrorTextSized",
			tip = "The red error lines and the yellow quest lines in the middle of the screen, also while Hide error messages is off. 100% is the game's size. With the options window open, a change shows a sample Not enough mana there." },
		{ key = "errorMana", kind = "bool", default = true, label = "Not enough mana", needs = "errors" },
		{ key = "errorPower", kind = "bool", default = true, label = "Not enough rage or energy", needs = "errors",
			tip = "Also not enough focus for a hunter's pet, and no combo points for a finishing move." },
		{ key = "errorRange", kind = "bool", default = true, label = "Out of range", needs = "errors",
			tip = "Also too far away to attack, too close for a ranged attack, and your pet out of range." },
		{ key = "errorFacing", kind = "bool", default = true, label = "Facing the wrong way", needs = "errors",
			tip = "Also the target not in front of you or not behind it, and your pet not behind its target." },
		{ key = "errorReady", kind = "bool", default = true, label = "Not ready yet", needs = "errors",
			tip = "Spells, abilities, items and potions still cooling down." },
		{ key = "errorTarget", kind = "bool", default = true, label = "No target or invalid target", needs = "errors",
			tip = "Also nothing to attack, and a dead target." },
		{ key = "errorMoving", kind = "bool", default = true, label = "Not while moving", needs = "errors",
			tip = "A cast or an action that needs you to stand still." },
		{ key = "errorSight", kind = "bool", default = false, label = "Not in line of sight", needs = "errors",
			tip = "Your target is behind a wall, a tree or a pillar." },
		{ key = "errorControl", kind = "bool", default = false, label = "While stunned, silenced or feared", needs = "errors",
			tip = "Also pacified, confused or charmed: the messages of a key you press while you cannot act." },
		{ key = "errorForm", kind = "bool", default = false, label = "Wrong stance or form", needs = "errors",
			tip = "Must be in Battle Stance, Can't use items while shapeshifted and the like: a key of a stance or form you are not in. Talking to an NPC while shapeshifted still says why it will not talk." },
		{ section = "Zone titles and talking head" },
		{ key = "zoneTitle", kind = "bool", default = false, label = "Hide the zone title",
			tip = "The big name that fades in near the top of the screen as you enter a zone, and its PvP line. The zone name on the minimap has its own row." },
		{ key = "subzoneTitle", kind = "bool", default = false, label = "Hide the subzone title",
			tip = "The smaller name of a part of a zone, such as a town, that fades in under it." },
		{ key = "zoneTitleSize", kind = "number", default = 100, min = 50, max = 150, step = 5, unit = "%", label = "Zone title size",
			tip = "The zone and subzone names that fade in near the top of the screen, and their PvP lines. With the options window open, a change shows a sample at their place for 3 seconds. Hidden ones stay hidden; 100% is the game's size." },
		{ key = "talkingHead", kind = "bool", default = false, label = "Hide the talking head",
			tip = "The portrait that speaks at the bottom of the screen, and its voice. One that already shows plays to its end." },
		{ section = "Timers" },
		{ key = "mirror", kind = "bool", default = true, label = "Breath and fatigue timers", tip = "Thin border and flat fill in the cast colours." },
		{ key = "mirrorTime", kind = "bool", default = true, label = "Seconds on the timers", needs = "mirror",
			tip = "Time left on the breath, fatigue and feign death bars, at the right under the bar, red under 10 seconds while it runs out." },
		{ key = "countdown", kind = "bool", default = true, label = "Countdown timers", tip = "Thin border and flat fill on pull and start timers." },
		{ section = "Damage meter" },
		{ key = "meter", kind = "bool", default = true, label = "Damage meter header", tip = "A flat band with a thin border in place of the default header." },
		{ key = "meterClear", kind = "choice", default = "off", label = "Clear the damage meter",
			choices = { { "off", "Off" }, { "enter", "When you enter a dungeon or raid" }, { "ask", "Ask when you enter one" } },
			tip = "Not again for the same instance within an hour, so a reload or a run back after a wipe keeps the numbers." },
		{ key = "meterClearBoss", kind = "bool", default = false, label = "At each raid boss", needs = "meterClear", needsIn = { "enter", "ask" },
			tip = "Clears as a raid boss fight starts, without asking." },
		{ section = "Queue and zone bars" },
		{ key = "queue", kind = "bool", default = true, label = "Queue status panel", tip = "Thin border in place of the default frame." },
		{ key = "zoneBars", kind = "bool", default = true, label = "Zone event bars", tip = "Thin border on score and progress bars." },
	},
	{
		key = "hudHitTable", label = "Hit table", owner = "hud",
		{ key = "hitTable", kind = "choice", default = "role", label = "Hit table under the player frame",
			choices = { { "role", "For tanks and damage dealers" }, { "on", "Always" }, { "off", "Off" } },
			tip = "Your chances against your target to miss, be dodged, parried or blocked, glance, crit and hit, worked out again as your gear, buffs, weapon skill and target change. Spells also get Resist: the share of a spell's damage resisted on average, with your Spell Piercing. Your target's own resistances are not known and count as none, so below 0 it is the damage a creature takes more from your piercing; a creature above you resists about 2% more a level, an estimate piercing does not lower, which a spell that also slows or roots pays with its higher miss instead. Piercing of one school, as Fire Piercing, counts in the gear comparison and a spell's Expected line. For tanks and damage dealers hides it while you count as a healer: by your group role, else a tank stance, form or aura, else the talent tree you put most points in, else your class (a priest heals), as Flat UI setup reads it. /flatui status says which you count as, and why. /flatui move places it; wherever it is, it steps down under the pet frame, or test mode's sample of it, where it would run into it." },
		{ key = "hitTableTip", kind = "choice", default = "role", label = "On enemy tooltips",
			choices = { { "role", "For tanks and damage dealers" }, { "on", "Always" }, { "off", "Off" } },
			tip = "Adds your hit table to the tooltip of an enemy you can attack: a line for each attack, as in Swing  M8 D6.5 G40 C12.1 H33.4 (M miss, D dodge, P parry, G glance, B block, C crit, H hit, in percent; on Spells, R a spell's damage resisted on average, as R-2.5 below 0 for the damage the enemy takes more from your Spell Piercing), against that enemy's level (a level shown as ??, or a boss of your level or above, counts as three levels above you). It counts Attacks, Special attacks, Where you stand (a tank counts in front) and Hit cap against a boss below, whatever Hit table under the player frame is set to. The game hides your stats in a fight, so there the numbers are from before it, and a line says so. For tanks and damage dealers leaves the lines out while you count as a healer. Needs Chat and tooltips on." },
		{ key = "hitTableTipCtrl", kind = "bool", default = true, label = "Only while Ctrl is held", needs = "hitTableTip", needsIn = { "role", "on" },
			tip = "The hit table's lines show on an enemy's tooltip only with Ctrl: held as the tooltip shows, or pressing Ctrl adds the lines; they leave when the tooltip next changes, not as you let go (over a unit frame, whose tooltip the game sets again every 0.2 seconds, they go with the key). Off, they show whenever the tooltip does." },
		{ key = "hitTableTipHint", kind = "bool", default = true, label = "Hint while Ctrl is up", needs = "hitTableTipCtrl",
			tip = "One dim line, Ctrl: your hit table against it, at the end of an enemy's tooltip while Ctrl is up, as items and spells have." },
		{ section = "What it shows" },
		{ key = "hitTableLines", kind = "choice", default = "auto", label = "Attacks",
			choices = { { "auto", "By your class and form" }, { "melee", "Melee" }, { "ranged", "Ranged" }, { "spell", "Spells" }, { "all", "Melee, ranged and spells" } },
			tip = "By your class and form: melee for a warrior or rogue, ranged for a hunter, melee and spells for a paladin or shaman, melee for a druid in Bear or Cat Form and spells out of them, spells for the others. Ranged needs a bow, gun, crossbow, thrown weapon or wand." },
		{ key = "hitTableSpecial", kind = "bool", default = true, label = "Special attacks",
			tip = "A line for your abilities under your swings: they do not glance or take the dual wield miss. Their crit, as on ranged attacks and spells, is the chance on an attack that lands." },
		{ key = "hitTableAgainst", kind = "choice", default = "target", label = "Against", needs = "hitTable", needsIn = { "role", "on" },
			choices = { { "target", "Your target" }, { "boss", "A boss three levels above you" } },
			tip = "With no enemy targeted, an enemy of your level. A target whose level shows as ?? counts as three levels above you." },
		{ key = "hitTableFacing", kind = "choice", default = "auto", label = "Where you stand",
			choices = { { "auto", "Behind, in front while it attacks you" }, { "behind", "Behind" }, { "front", "In front" } },
			tip = "From the front an enemy can also parry and block. The game does not tell where you stand: the first choice counts you in front while you hold your target's threat, as a tank does." },
		{ key = "hitTableRules", kind = "choice", default = "classic", label = "Hit cap against a boss",
			choices = { { "classic", "9% melee, 16% spells (Classic tests)" }, { "game", "8% melee, 17% spells (the game's tooltip)" } },
			tip = "Tests of Classic found the first 1% of your hit lost against a boss and 1% of spells always missing. The hit tooltip of the character sheet leaves both out. Which holds on WoW: Forever is not known yet." },
		{ section = "When it shows" },
		{ key = "hitTableShow", kind = "choice", default = "target", label = "Show", needs = "hitTable", needsIn = { "role", "on" },
			choices = { { "target", "With an enemy targeted" }, { "combat", "In combat" }, { "always", "Always" } } },
		{ section = "Look" },
		{ key = "hitTableFont", kind = "choice", default = "sans", label = "Font", needs = "hitTable", needsIn = { "role", "on" },
			choices = { { "sans", "Flat UI Sans" }, { "game", "Game font" } },
			tip = "Flat UI Sans is IBM Plex Sans. A language it has no letters for keeps the game font." },
		{ key = "hitTableSize", kind = "choice", default = "100", label = "Text size", choices = HIT_TABLE_SIZES,
			tip = "100% is 11 px. While the target frame stands right beside your player frame, the text gets smaller so the table ends before it.",
			needs = "hitTable", needsIn = { "role", "on" } },
		{ key = "hitTableBack", kind = "bool", default = true, label = "Background and border", needs = "hitTable", needsIn = { "role", "on" },
			tip = "A flat background with a thin border, in the colours of the Flat UI page, or of Own border and background on the Minimap page." },
		{ key = "hitTableTipSize", kind = "choice", default = "100", label = "Text size on enemy tooltips", choices = HIT_TABLE_SIZES,
			tip = "The hit table's lines on an enemy's tooltip, in a share of the size of the tooltip's text. The other lines, and every tooltip after it, keep the game's size.",
			needs = "hitTableTip", needsIn = { "role", "on" } },
	},
	{
		key = "chat", label = "Chat", moduleLabel = "Chat and tooltips",
		{ key = "enabled", kind = "bool", default = true, label = "Restyle chat and tooltips",
			tip = "One switch for Chat, Tooltips, Spell tooltips and Gear comparison." },
		{ section = "Chat windows" },
		{ key = "frames", kind = "bool", default = true, label = "Chat window background" },
		{ key = "opacity", kind = "number", default = 60, min = 0, max = 100, step = 5, unit = "%", label = "Chat window opacity",
			tip = "Replaces the opacity in the chat window settings.", needs = "frames" },
		{ key = "tabs", kind = "bool", default = true, label = "Chat tabs" },
		{ key = "tabOpacity", kind = "choice", default = "clear", label = "Chat tab opacity", needs = "tabs",
			tip = "How bright the tab names are.",
			choices = { { "game", "As the game has it" }, { "clear", "Selected 100%, others 60%" }, { "full", "All 100%" } } },
		{ key = "buttons", kind = "bool", default = true, label = "Chat button background" },
		{ key = "frameBorder", kind = "bool", default = true, label = "Chat window border", needs = "frames" },
		{ section = "Chat input" },
		{ key = "editbox", kind = "bool", default = true, label = "Chat input box" },
		{ key = "inputPlace", kind = "choice", default = "below", label = "Input box position",
			choices = { { "below", "Below the chat window" }, { "above", "Above the chat window" } } },
		{ key = "inputIdle", kind = "number", default = 35, min = 0, max = 100, step = 5, unit = "%", label = "Input box opacity when idle" },
		{ key = "inputFocus", kind = "choice", default = "type", label = "Border while typing", needs = "editbox",
			choices = { { "type", "Chat type colour" }, { "accent", "Highlight colour" }, { "plain", "Plain border" } } },
		{ key = "inputLeft", kind = "bool", default = true, label = "Letters left while typing", needs = "editbox",
			tip = "Once 50 or fewer letters are left in a chat line, a small count at the right of the input box shows how many, amber at 20 and red at 0. A link counts only its name, and the typed text stops short of the count while it shows." },
		{ key = "arrows", kind = "bool", default = true, label = "Arrow keys without Alt",
			tip = "While you type, the arrow keys move the cursor and Up and Down bring back the lines you sent. Off, they turn and move your character as the game has it, and edit the text with Alt held." },
		{ section = "Border and background" },
		{ key = "lookOwn", kind = "bool", default = false, label = "Own border and background" },
		{ key = "lookBorder", kind = "colour", default = "ff000000", label = "Border colour", needs = "lookOwn" },
		{ key = "lookBack", kind = "colour", default = "ff0f0f0f", label = "Background colour", needs = "lookOwn" },
		{ key = "lookBackAlpha", kind = "number", default = 85, min = 0, max = 100, step = 5, unit = "%", label = "Background opacity", needs = "lookOwn" },
	},
	{
		key = "chatText", label = "Chat text", parent = "chat", owner = "chat",
		{ section = "Game settings" },
		{ key = "timestamps", kind = "choice", default = "none", cvar = "showTimestamps", label = "Timestamps",
			choices = { { "none", "None" }, { "hhmm", "03:27" }, { "hhmmss", "03:27:32" }, { "hhmmAm", "03:27 PM" }, { "hhmmssAm", "03:27:32 PM" },
				{ "hhmm24", "15:27" }, { "hhmmss24", "15:27:32" } },
			values = { none = "none", hhmm = TIMESTAMP_FORMAT_HHMM or "%I:%M ", hhmmss = TIMESTAMP_FORMAT_HHMMSS or "%I:%M:%S ",
				hhmmAm = TIMESTAMP_FORMAT_HHMM_AMPM or "%I:%M %p ", hhmmssAm = TIMESTAMP_FORMAT_HHMMSS_AMPM or "%I:%M:%S %p ",
				hhmm24 = TIMESTAMP_FORMAT_HHMM_24HR or "%H:%M ", hhmmss24 = TIMESTAMP_FORMAT_HHMMSS_24HR or "%H:%M:%S " } },
		{ key = "classColour", kind = "choice", default = "always", cvar = "chatClassColorOverride", label = "Class colours in chat",
			choices = { { "always", "Always" }, { "never", "Never" }, { "channel", "Per channel" } },
			values = { always = "0", never = "1", channel = "2" } },
		{ section = "Font" },
		{ key = "font", kind = "choice", default = "default", label = "Chat font", choices = "FontChoices" },
		{ key = "outline", kind = "choice", default = "game", label = "Chat text outline", choices = "OutlineChoices" },
		{ key = "shadow", kind = "bool", default = true, label = "Chat text shadow" },
		{ section = "History and fading" },
		{ key = "history", kind = "number", default = 128, min = 128, max = 2048, step = 64, unit = " lines", label = "Lines kept per window" },
		{ key = "fade", kind = "bool", default = true, label = "Fade old messages" },
		{ key = "fadeAfter", kind = "number", default = 120, min = 10, max = 600, step = 10, unit = " s", label = "Fade after", needs = "fade" },
		{ key = "restore", kind = "bool", default = false, label = "Show recent chat after a reload",
			tip = "Each time you reload or log in, the lines of the last hour show again in your main chat window: say, yell, emotes, party, raid, guild, officer and whispers. They are kept in Flat UI's saved settings of this character; lines the game withholds in fights and dungeons are not kept." },
		{ key = "restoreLines", kind = "number", default = 50, min = 10, max = 200, step = 10, unit = " lines", label = "Lines to show again",
			tip = "None older than an hour, and no more than three quarters of Lines kept per window, so that the other lines of a login stay in the window.", needs = "restore" },
		{ key = "restoreChannels", kind = "bool", default = false, label = "Numbered channels too",
			tip = "General, Trade and the other numbered channels: in Copy recent chat, and after a reload with Show recent chat after a reload." },
		{ key = "copyChat", kind = "list", default = 0, label = "Copy recent chat", none = "Choose", items = "ChatCopyLines", pick = "ChatCopyPick",
			tip = "Opens a box with the last lines Flat UI heard, ready for Ctrl+C: say, yell, emotes, party, raid, guild, officer and whispers. Numbered channels too adds General, Trade and the other numbered channels. Each reads as [21:04] [Party] [Mara]: text, links as their name in brackets. Not in a fight. /flatui copy does the same. Ctrl+A selects every line again after a click in the box. A key for it is under Flat UI in the game's Key Bindings." },
		{ section = "Channels" },
		{ key = "channelNames", kind = "choice", default = "short", label = "Channel names",
			tip = "The label before a line of General, Trade, LocalDefense and the other numbered channels. A click on it still opens the channel.",
			choices = { { "game", "As the game has it ([2. Trade - City])" }, { "short", "Number and name ([2. Trade])" } } },
		{ section = "Links" },
		{ key = "webLinks", kind = "bool", default = true, label = "Web addresses as links",
			tip = "A web address in a chat line becomes a link. A click on it shows the address selected in a box, ready to copy; Ctrl+C there closes the box a moment later. Not in a fight: chat then says to click it again after." },
		{ key = "linkTips", kind = "bool", default = true, label = "Tooltips of chat links",
			tip = "While the mouse is over an item, spell, achievement or quest link in a chat window, its tooltip shows. Not in a fight." },
		{ section = "Mentions" },
		{ key = "mentions", kind = "bool", default = true, label = "Your name in chat",
			tip = "Your name in what other players write in say, yell, emotes, party, raid, guild, officer and the numbered channels shows in a colour of its own. Not in whispers, and only the whole name." },
		{ key = "mentionColour", kind = "colour", default = "ffff9933", label = "Your name colour", needs = "mentions" },
		{ key = "mentionSound", kind = "choice", default = "none", label = "Sound when you are named", needs = "mentions",
			tip = "Once for each line that names you, at most once a second. Picking one plays it.",
			choices = { { "none", "None" }, { "spell", "Spell alert" }, { "chimes", "Chimes" }, { "bell", "Bell" }, { "warhorn", "Warhorn" },
				{ "raid", "Raid warning" }, { "alarm", "Alarm" }, { "whisper", "Whisper warning" } } },
		{ key = "mentionTab", kind = "bool", default = true, label = "Light the tab that names you", needs = "mentions",
			tip = "When a line names you in a chat window whose tab is not chosen (a Trade, Guild or LFG tab), that tab's box and label take Your name colour with a slow pulse until you click the tab, and a small number at its top right corner counts the lines that named you there (up to 9+). Needs Chat tabs on the Chat page." },
		{ key = "mentionWords", kind = "list", default = 0, label = "Other words to colour", none = "Add one, or choose one to stop colouring it",
			items = "ChatWordLines", pick = "ChatWordPick", needs = "mentions",
			tip = "Add a word... opens a box: type the word and press Enter. Up to 20 for all your characters: whole words, any case, in Your name colour and with Sound when you are named. Choose a word to stop colouring it. /flatui words add tank does the same." },
	},
