			tip = "The guild line of a player: green for your own guild, blue for another, with the member's rank after it." },
		{ section = "Size and text" },
		{ key = "tipScale", kind = "number", default = 100, min = 50, max = 200, step = 5, unit = "%", label = "Tooltip size" },
		{ key = "tipTitleSize", kind = "number", default = 100, min = 50, max = 200, step = 5, unit = "%", label = "Title size" },
		{ key = "tipTextSize", kind = "number", default = 100, min = 50, max = 200, step = 5, unit = "%", label = "Text size" },
		{ section = "Tooltip health bar" },
		{ key = "health", kind = "bool", default = true, label = "Health bar border and fill" },
		{ key = "barTexture", kind = "choice", default = "default", label = "Bar texture", needs = "health", choices = "BarChoicesDefault" },
		{ key = "barColour", kind = "choice", default = "class", label = "Health bar colour", needs = "barHide", needsIn = { false },
			tip = "The colour of the health bar under a unit's tooltip, kept through every change of its health, also in a fight.",
			choices = { { "class", "Class colour for players, reaction for the rest" }, { "game", "Green, as the game has it" } } },
		{ key = "barHide", kind = "bool", default = false, label = "Hide the health bar" },
		{ key = "barHeight", kind = "number", default = 8, min = 2, max = 16, step = 1, unit = " px", label = "Health bar height",
			needs = "barHide", needsIn = { false } },
		{ key = "barText", kind = "choice", default = "pct", label = "Health text on the bar", needs = "barHide", needsIn = { false },
			tip = "The health of the unit in a small outlined text on the tooltip's health bar, kept up to date while you point at the unit, also in a fight. Its size follows Health bar height, and a bar under 5 px has none; a dead unit reads Dead.",
			choices = { { "none", "None" }, { "pct", "Percent" }, { "curmax", "Current / max" }, { "curpct", "Current and percent" } } },
	},
	{
		key = "chatTipsMore", label = "Combat and extra lines", parent = "chatTips", owner = "chat",
		{ section = "Fade" },
		{ key = "fadeOut", kind = "choice", default = "fast", label = "Fade out",
			choices = { { "game", "As the game has it" }, { "fast", "Fast" }, { "now", "At once" } } },
		{ section = "Combat" },
		{ key = "combat", kind = "choice", default = "show", label = "Tooltips in combat",
			choices = { { "show", "Show as usual" }, { "units", "Hide unit tooltips" }, { "all", "Hide every tooltip" } } },
		{ key = "combatKey", kind = "choice", default = "none", label = "Show anyway while holding",
			choices = { { "none", "No key" }, { "shift", "Shift" }, { "ctrl", "Ctrl" }, { "alt", "Alt" } } },
		{ key = "combatUnits", kind = "choice", default = "all", label = "Unit tooltips hidden", tip = "A unit the game will not say about is shown.",
			needs = "combat", needsIn = { "units" }, choices = { { "all", "Every unit" }, { "enemies", "Enemies" }, { "friends", "Friendly units" } } },
		{ key = "combatWhere", kind = "choice", default = "combat", label = "Where", tip = "With In combat in dungeons and raids, tooltips show in fights in the open world.",
			needs = "combat", needsIn = { "units", "all" }, choices = { { "combat", "In combat" }, { "instance", "In combat in dungeons and raids" } } },
		{ key = "spellTips", kind = "choice", default = "show", label = "Spell tooltips", tip = "Show anyway while holding still shows them.",
			choices = { { "show", "Show" }, { "combat", "Hide in combat" }, { "instance", "Hide in dungeons and raids" }, { "always", "Hide always" } } },
		{ key = "auraTips", kind = "choice", default = "show", label = "Buff and debuff tooltips",
			tip = "Your own buffs and debuffs, and those on party and raid frames. The target and focus frames show theirs in a tooltip of the game's own that Flat UI cannot hide. Show anyway while holding still shows them.",
			choices = { { "show", "Show" }, { "combat", "Hide in combat" }, { "instance", "Hide in dungeons and raids" }, { "always", "Hide always" } } },
		{ key = "itemTips", kind = "choice", default = "show", label = "Item tooltips", tip = "Show anyway while holding still shows them.",
			choices = { { "show", "Show" }, { "combat", "Hide in combat" }, { "instance", "Hide in dungeons and raids" }, { "always", "Hide always" } } },
		{ key = "groupTips", kind = "choice", default = "other", label = "Party and raid frame tooltips",
			tip = "The unit tooltips of the game's party and raid frames, whose clicks do not change. The box of buffs and debuffs that opens beside a party frame still shows.",
			choices = { { "other", "As other units" }, { "ooc", "Out of combat only" }, { "key", "Only with a key" }, { "off", "Off" } } },
		{ key = "groupTipKey", kind = "choice", default = "shift", label = "Key for party and raid frames",
			tip = "Hold it as you point at one of these frames, and its tooltip shows, unless Tooltips in combat hides it.",
			needs = "groupTips", needsIn = { "key" }, choices = { { "shift", "Shift" }, { "ctrl", "Ctrl" }, { "alt", "Alt" } } },
		{ section = "Extra lines" },
		{ key = "ids", kind = "bool", default = true, label = "Item, spell, quest and NPC IDs",
			tip = "A grey line at the end of the tooltip: Item ID, Spell ID, Quest ID on a quest link, Currency ID on a currency, and on a creature NPC ID." },
		{ key = "iconId", kind = "bool", default = false, label = "Icon ID", tip = "The number of the icon file, after the ID line.", needs = "ids" },
		{ key = "idsWhen", kind = "choice", default = "always", label = "Show IDs", needs = "ids",
			tip = "The IDs show while the key is held: at once over bags, action bars and the Character window, and over a link once you point at it again.",
			choices = { { "always", "Always" }, { "shift", "While holding Shift" }, { "ctrl", "While holding Ctrl" }, { "alt", "While holding Alt" } } },
		{ key = "enchantId", kind = "bool", default = true, label = "Temporary enchant ID", tip = "On a weapon you wear: the ID of its poison, oil, stone or imbue.", needs = "ids" },
		{ key = "count", kind = "bool", default = true, label = "Item count in bags and bank",
			tip = "How many you carry, and with your bank. When Counts in tooltips on the Bags page names this character, its line takes this one's place." },
		{ key = "itemLevel", kind = "bool", default = true, label = "Item level", tip = "On armor and weapons, as Item level 63 in gold, also in the comparison beside them." },
		{ key = "icons", kind = "bool", default = true, label = "Item and spell icons",
			tip = "The icon before the name of an item, a spell, a buff or a debuff: not on the target and focus frames, whose buff tooltip is the game's own." },
		{ key = "auraCaster", kind = "bool", default = true, label = "Who cast a buff or debuff",
			tip = "A grey line under a buff's or debuff's tooltip naming who cast it, in their class colour: You, your pet, a group member, a group member's pet (as Mara's pet (Imp)) or an enemy. On your own buffs and debuffs and those on party and raid frames. The target and focus frames use a tooltip of the game's own that Flat UI cannot add to." },
		{ key = "targetLine", kind = "bool", default = true, label = "Target of units", tip = "A line naming what a unit targets, in its class or reaction colour: You when it is you, in red while it is a unit you can attack." },
		{ key = "targetedBy", kind = "bool", default = true, label = "Who in your group targets it",
			tip = "In a party or raid, a grey line under a unit's tooltip naming the members whose target it is, in their class colours: at most six, then +N. Kept up to date while you point at the unit, and it shows as soon as a first member takes it." },
		{ section = "Item comparison" },
		{ key = "compareShift", kind = "bool", default = true, label = "Compare items only while holding Shift",
			tip = "The items you wear show beside the tooltip of an item only while you hold Shift. Sets a game setting that the game's options do not show. Turned off, the game's own value is back." },
		{ key = "compareHint", kind = "bool", default = true, label = "Hint while Shift is up", needs = "compareShift",
			tip = "An item you could wear ends its tooltip with a dim line, Shift: compare with what you wear, and your spells while the gear lines wait for the comparison. It goes once you hold Shift; not on the items you wear." },
	},
	{
		key = "chatSpells", label = "Spell tooltips", owner = "chat",
		{ section = "Lines" },
		{ key = "spellPower", kind = "bool", default = true, label = "Spell power and attack power lines",
			tip = "What share of your spell damage, spell healing or attack power a spell or ability adds: a cast, a tick or a target, and for weapon abilities their weapon damage and the share of attack power the weapon's speed gives. WoW: Forever's own values, from the game's spell data and tooltips and, where they do not say, from tests in the game (many by wowsims/forever), Blizzard's notes and a few rules of the wowsims/forever simulator. ~ marks an estimate." },
		{ key = "spellStats", kind = "bool", default = true, label = "With your stats",
			tip = "How much that share is with your stats now, and the threat your attack power adds. The game withholds your stats in fights: then the numbers are those from before the fight, and a line says so." },
		{ key = "spellTotal", kind = "bool", default = true, label = "Total of a cast", needs = "spellPower",
			tip = "What one cast does now with your stats, the rank's own base and what your stats add together, as in Total 973 a cast (556 + 417), or Shield Slam Rank 4 with 101 block value, Total 857 a hit (655 + 202). A spell over time says its total over its duration and a tick, a channel its whole channel, a heal its healing, and a weapon strike one hit with the weapon you wear." },
		{ key = "spellRates", kind = "bool", default = true, label = "Average and rates", needs = "spellTotal",
			tip = "Dim lines under the total, each with its figure on the right: Expected, what that total does on average with crits, misses and, for a spell, the damage your Spell Piercing adds, against the enemy Against names under Gear comparison, so it is less than the total but for what crits add; Per second, of cast time (of the global cooldown for an instant); and for a spell that costs mana, Per mana, a point of mana, with how many casts a full bar of mana gives." },
		{ key = "spellLowRank", kind = "bool", default = true, label = "Less for low ranks (estimate)",
			tip = "On WoW: Forever a rank far below your level gets less of your spell damage and healing. Blizzard gave no formula, so Flat UI uses an estimate from players' tests on heals up to level 30: in full for 17 levels after the rank is learned, then 5% less a level. Marked ~." },
		{ key = "spellNextRank", kind = "bool", default = true, label = "Next rank",
			tip = "On a spell with more ranks: the level of the next rank, as Next rank: Rank 6 at level 32, or in green that you can learn it now. A rank no trainer teaches, from the class books of Ahn'Qiraj, says it comes from a book. Not at the top rank or once you know a higher one, nor on talents, pet spells and judgements." },
		{ key = "spellThreat", kind = "choice", default = "special", label = "Threat lines",
			choices = { { "special", "Where threat is special or changed" }, { "all", "On every spell" }, { "off", "Off" } },
			tip = "Where threat is special or changed: abilities with threat of their own, and spells whose threat your stance, form, Righteous Fury, talents or gear change; not a damage dealer's Battle Stance or Cat Form, nor heals at the usual half a point a point healed. With your stats the line gives the threat of one hit or cast, from the same total as Total of a cast, and under it how it is made and each multiplier, as Shield Slam in Defensive Stance with Defiance 3/3: ~2,401 a hit, (damage + ~255) x 2.16, Defensive Stance x1.8, Defiance 3/3 x1.2. A flat threat gives its number too, as Sunder Armor's 552 with 1,000 attack power; a taunt and a rule with no number a hit say their rule in words. Stances, forms and Righteous Fury say what their own text does not. A spell whose threat on WoW: Forever is not known, such as Whirlwind, Execute, Power Word: Shield and the absorbs, gets no line." },
		{ section = "Showing" },
		{ key = "spellWhen", kind = "choice", default = "always", label = "Show spell lines",
			choices = { { "always", "Always" }, { "shift", "While holding Shift" }, { "ctrl", "While holding Ctrl" }, { "alt", "While holding Alt" } },
			tip = "With a key, the lines come as it goes down over action bars, and in the spell book and over a link once you point at it again. A spell link you click in chat shows them at every choice: the game opens its tooltip only for a plain click and never builds it again as a key goes down." },
		{ key = "spellHint", kind = "bool", default = true, label = "Hint while the key is up", needs = "spellWhen", needsIn = { "shift", "ctrl", "alt" },
			tip = "While Show spell lines waits for a key, a spell Flat UI has lines for ends its tooltip with one dim line, as Shift: your numbers for this spell, which goes as you hold the key and the lines come. Only on spells that get lines with the options you chose." },
		{ key = "tipDetail", kind = "choice", default = "compact", label = "Notes under the lines",
			choices = { { "compact", "Compact" }, { "full", "Full" } },
			tip = "For spell and item tooltips alike. Compact keeps at most one dim line of notes under each block, its notes joined; Full shows every note, such as what a multiplier comes from or why a figure is an estimate. The rates under a spell's total and how its threat is made are short dim lines that show in both." },
	},
	{
		key = "gearCompare", label = "Gear comparison", owner = "chat",
		{ section = "Item tooltips" },
		{ key = "gear", kind = "bool", default = true, label = "Your spells in item tooltips",
			tip = "An item you could wear says how it changes the damage, healing or threat of the spells you chose, against what you wear in its slot, before armor, resistances (a spell counts only the damage your Spell Piercing adds) and the talents and buffs your stats do not show, such as talents that turn one stat into another or add crit to one school. On the Character window an item says what it gives. The Gear comparison window shows all of them." },
		{ key = "gearWhen", kind = "choice", default = "compare", label = "Show gear lines", needs = "gear",
			choices = { { "compare", "With the game's comparison" }, { "always", "Always" }, { "shift", "While holding Shift" }, { "ctrl", "While holding Ctrl" },
				{ "alt", "While holding Alt" } },
			tip = "With the game's comparison: while the items you wear show beside the tooltip, which is while you hold Shift with Compare items only while holding Shift on the Tooltips page (Combat and extra lines tab). On the Character window, while you hold Shift. An item link you click in chat shows them at every choice: the game opens its tooltip only for a plain click and never builds it again as a key goes down." },
		{ key = "gearMost", kind = "number", default = 5, min = 1, max = 8, step = 1, unit = " spells", label = "Spells in an item tooltip", needs = "gear" },
		{ key = "gearTotals", kind = "choice", default = "weighted", label = "Overall change",
			choices = { { "weighted", "Weighted" }, { "off", "Off" } },
			tip = "One line at the top of an item's lines and of the Gear comparison window with what the item does overall: the change in what the spells you chose do in a minute, in damage, healing and threat, your swings and shots for the whole minute and each other spell as often as a minute of WoWSims' rotation for your class uses it (Heroic Strike and Maul on the share of your swings it gives them), where Flat UI has one for your class and talents, else for an even share of the global cooldowns, each times its weight (1 unless you set another in the window, from 0 to 5), and Damage taken where avoidance shows. Green is better, red worse, and the best and the worst spell are named in the window, whose Overall tooltip says which rotation counts." },
		{ section = "Against" },
		{ key = "gearAgainst", kind = "choice", default = "auto", label = "Against",
			choices = { { "auto", "A boss at level 60, else an enemy of your level" }, { "level", "An enemy of your level" }, { "boss", "A boss three levels above you" } },
			tip = "Misses, dodges, parries, glancing blows and crits counted as the hit table counts them against this enemy, in item tooltips and the window. A damage spell also counts the damage your Spell Piercing adds (the piercing of one school, as Fire Piercing, for that school's spells), but not the share an enemy above you resists for its levels." },
		{ key = "gearFacing", kind = "choice", default = "role", label = "Where you stand",
			choices = { { "role", "In front as a tank, else behind" }, { "behind", "Behind" }, { "front", "In front" } },
			tip = "From the front an enemy also parries and blocks. Your role is read as for the hit table." },
		{ key = "gearRules", kind = "choice", default = "hittable", label = "Hit cap against a boss",
			choices = { { "hittable", "As on the Hit table page" }, { "classic", "9% melee, 16% spells (Classic tests)" }, { "game", "8% melee, 17% spells (the game's tooltip)" } },
			tip = "As on the Hit table page follows its Hit cap against a boss, also while the hit table is off. Which holds on WoW: Forever is not known yet." },
		{ section = "Tanking" },
		{ key = "gearAvoid", kind = "choice", default = "role", label = "Avoidance",
			choices = { { "role", "For tanks" }, { "on", "Always" }, { "off", "Off" } },
			tip = "In item tooltips and the window's Avoidance view: how an item changes the chance that an enemy's swing misses you, is dodged, parried or blocked, crits or crushes, and what your armor and block value take off, against the enemy of Against. For tanks: while your role reads tank, as for the hit table. The rules of misses, crits and crushing blows are the game's; the rest are Classic's, marked ~." },
		{ key = "gearSwing", kind = "number", default = 1500, min = 200, max = 6000, step = 100, unit = "", label = "Enemy hit for block value",
			needs = "gearAvoid", needsIn = { "role", "on" },
			tip = "Damage taken counts an enemy's swing after misses, dodges, parries, blocks, crits and crushing blows and after your armor. A blocked swing loses your block value, at most the whole hit: this is the size of that hit before armor. Set it near what the enemies you tank hit for. It is an estimate." },
		{ section = "Spells counted" },
		{ key = "gearAdd", kind = "list", default = 0, label = "Add a spell", none = "Choose a spell", items = "GearCandidates", pick = "GearAdd",
			tip = "Your spells Flat UI can work out, and your auto attack, Auto Shot or wand. For one not listed, type /flatui gear add and its name; a shift-clicked spell keeps its rank. Until you add or remove one, your class's main spells for your role are used. The list serves item tooltips and the window." },
		{ key = "gearRemove", kind = "list", default = 0, label = "Remove a spell", none = "Choose a spell", items = "GearPicked", pick = "GearRemove" },
		{ key = "gearBar", kind = "list", default = 0, label = "Add the spells of a bar", none = "Choose a bar", items = "GearBarLines", pick = "GearBarPick",
			tip = "Each spell on that bar Flat UI can work out, with the rank on the bar, which counts for a low rank you keep there. Action bar 1 is the one the main bar shows now." },
		{ key = "gearReset", kind = "list", default = 0, label = "Back to your class's spells", none = "Choose", items = "GearResetLines", pick = "GearResetPick",
			tip = "Your class's main spells for your role, which follow your role and form until you add or remove one." },
	},
	{
		key = "gearWindow", label = "Window and finder", parent = "gearCompare", owner = "chat",
		{ section = "Window" },
		{ key = "gearOpen", kind = "list", default = 0, label = "Gear comparison window", none = "Choose", items = "GearOpenLines", pick = "GearOpenPick",
			tip = "Every spell you chose, now and with an item you drop on it. /flatui gear opens it too, and so does an Alt-click on an item link in chat, with that item. Shift-click the item there to link it in chat, Ctrl-click to try it on, and Shift-click the Overall line to put the verdict in chat. Drag its bottom right corner to size it, and set each spell's weight for the Overall line there. A key for it is under Flat UI in the game's Key Bindings." },
		{ key = "gearCharButton", kind = "bool", default = true, label = "Button on the Character window", changed = "GearButtonChanged",
			tip = "A Compare gear button on the title bar of the Character window, left of the close button, opens and closes the Gear comparison window; its words light up while the window is open. With an item on the cursor, or one dropped on it, the window compares that item. Right-click opens the item finder. Move it with /flatui move (Compare gear button): it keeps its place on the Character window." },
		{ key = "gearWinFont", kind = "number", default = 12, min = 10, max = 16, step = 1, label = "Window text size",
			tip = "The size of the text in the Gear comparison window." },
		{ key = "gearWinReset", kind = "list", default = 0, label = "Reset the window", none = "Choose", items = "GearWindowResetLines", pick = "GearWindowResetPick",
			tip = "Puts the Gear comparison window back at its first size and place. A double-click on its title bar does the same." },
		{ section = "Item finder" },
		{ key = "gearFind", kind = "list", default = 0, label = "Item finder", none = "Choose", items = "GearFindLines", pick = "GearFindPick",
			tip = "Opens the Gear comparison window with the item finder beside it: find items by name, slot, armor or weapon type, level and quality, among the armor and weapons of the game, in your bags and bank, or on your other characters. Click one to compare it, right-click to compare against it, Shift-click to link it, Ctrl-click to try it on. The Find button of the window opens it too." },
		{ key = "gearFindLevel", kind = "choice", default = "near", label = "Levels the finder starts with",
			choices = { { "near", "Near your level" }, { "any", "Any level" } },
			tip = "Near your level starts the finder on items you need at most your level + 5 to wear. You can change the levels in the finder." },
		{ key = "gearFindUsable", kind = "bool", default = true, label = "Only what you can wear",
			tip = "The finder starts with only the armor and weapon types your class can learn, and items for your class. You can change it in the finder." },
	},
	{
		key = "trinkets", label = "Trinket queue",
		{ key = "enabled", kind = "bool", default = true, label = "Trinket queue",
			tip = "A list of your trinkets for each trinket slot, best first. With a slot's Auto queue on, whenever the trinket you wear is on cooldown Flat UI puts on the highest one of the list that you carry and that is ready, and goes back to a higher one as soon as it is ready again; only out of a fight, since the game changes no trinket in one. /flatui queue, the small square beside each trinket slot on the Character window or Trinket queue window opens the lists. The lists and each slot's Auto queue are kept for each character." },
		{ section = "Auto queue" },
		{ key = "autoTop", kind = "bool", default = false, label = "Top trinket slot", get = "TrinketAutoGet", set = "TrinketAutoSet",
			tip = "Swaps the top trinket slot by its list. Also the Auto queue box in the window and a right-click on the slot's square. Kept for this character, whatever profile is in use." },
		{ key = "autoBottom", kind = "bool", default = false, label = "Bottom trinket slot", get = "TrinketAutoGet", set = "TrinketAutoSet",
			tip = "Swaps the bottom trinket slot by its list. Also the Auto queue box in the window and a right-click on the slot's square. Kept for this character, whatever profile is in use." },
		{ key = "ready", kind = "number", default = 30, min = 0, max = 60, step = 5, unit = " s", label = "Ready with this much left",
			tip = "A trinket whose cooldown has this many seconds or fewer left counts as ready: putting on a trinket with a use starts a 30 second cooldown on it anyway. At 0 only a trinket off cooldown counts. A trinket just put on is never swapped for a lower one in that 30 seconds." },
		{ key = "window", kind = "list", default = 0, label = "Trinket queue window", none = "Choose a slot", items = "TrinketWindowLines", pick = "TrinketWindowPick",
			tip = "Opens the window on that slot's list: add trinkets from your bags, put them in order, set a delay or Stop, and pause the queue. /flatui queue opens it too. A key for it is under Flat UI in the game's Key Bindings." },
		{ section = "When it swaps" },
		{ key = "say", kind = "bool", default = true, label = "Say each swap in chat",
			tip = "One line with the trinket put on and the one it replaced, and why." },
		{ key = "sound", kind = "choice", default = "none", label = "Sound on a swap",
			tip = "Plays once as the queue puts a trinket on. Picking one plays it.",
			choices = { { "none", "None" }, { "spell", "Spell alert" }, { "chimes", "Chimes" }, { "bell", "Bell" }, { "warhorn", "Warhorn" },
				{ "raid", "Raid warning" }, { "alarm", "Alarm" }, { "whisper", "Whisper warning" } } },
		{ key = "riding", kind = "choice", default = "off", label = "Carrot on a Stick while riding",
			tip = "Getting on a mount puts Carrot on a Stick in that slot; getting off puts your trinket back: the best ready one of the slot's list while its Auto queue is on, else the one it replaced. Only out of a fight, and only a bound Carrot on a Stick in your bags. A trinket with a use put back on starts its 30 second cooldown, as with any swap. A trinket you change yourself while riding stays until your next mount.",
			choices = { { "off", "Off" }, { "bottom", "Bottom trinket slot" }, { "top", "Top trinket slot" } } },
		{ section = "Character window" },
		{ key = "slotButtons", kind = "bool", default = true, label = "Buttons by the trinket slots", changed = "TrinketButtonsChanged",
			tip = "A small square right of each trinket slot: its colour says whether that slot's queue is on, waits for the end of a fight or for a delay, is held or paused, or is off; point at it for why; the tooltip follows each click and counts down. Click it for the window, Shift-click for Queue now on that slot, right-click to turn that slot's queue on or off, Shift-right-click to pause or resume every swap, drop a trinket on it to add it to that slot's list." },
		{ key = "tipLine", kind = "bool", default = true, label = "Queue line on trinket tooltips",
			tip = "A dim last line on a trinket's tooltip, in your bags or on the Character window, says where it stands in a list, as Trinket queue: 2nd of 4, top slot, with its Stop or delay and whether that slot's Auto queue is off. A trinket in both lists gets a line for each." },
	},
	{
		key = "errands", label = "Errands",
		{ key = "enabled", kind = "bool", default = true, label = "Run errands",
			tip = "Each errand below and on the Popups and invites and Quests and levelling tabs has its own row. Selling, repairs, Make room, Train all, summons, invites, new spell ranks and talent reminders wait for the end of a fight." },
		{ key = "chat", kind = "bool", default = true, label = "Say what was done", tip = "A line in chat after selling, repairing, training, deleting, accepting, declining and upranking, and when a quest is left to you. Also after Sell junk, Deposit and Take out of the Bags page, whatever the switch of Errands." },
		{ section = "Merchant" },
		{ key = "sell", kind = "bool", default = true, label = "Sell grey items",
			tip = "When a merchant opens. Hold Shift as it opens to keep them that time, and chat says how many it kept. /flatui sell and /flatui keep choose other items to sell or keep." },
		{ key = "sellTwelve", kind = "bool", default = true, label = "Sell at most 12 at a time", needs = "sell",
			tip = "Grey items are sold in one go. Items of your sell list that are not grey come after them, at most 12 at a time, so the merchant's buyback still holds them; Sell next 12 sells the next ones. The Sell junk button of the Bags page follows it too, whatever the switch of Errands." },
		{ key = "sellList", kind = "list", default = 0, label = "Items always sold", none = "Choose one to stop selling it", items = "ErrandsSellLines",
			pick = "ErrandsSellPick", tip = "/flatui sell and an item adds one." },
		{ key = "keepList", kind = "list", default = 0, label = "Items never sold", none = "Choose one to sell it again", items = "ErrandsKeepLines",
			pick = "ErrandsKeepPick", tip = "/flatui keep and an item adds one. Make room never deletes them either." },
		{ key = "repair", kind = "choice", default = "own", label = "Repair", tip = "When a merchant who repairs opens. With items sold too, one chat line says both.",
			choices = { { "off", "Off" }, { "own", "With your gold" }, { "guild", "Guild gold first" } } },
		{ key = "guildWhere", kind = "choice", default = "everywhere", label = "Guild gold where", needs = "repair", needsIn = { "guild" },
			tip = "Elsewhere the repair is paid with your own gold.",
			choices = { { "everywhere", "Everywhere" }, { "group", "In a group or an instance" }, { "instance", "In dungeons, raids and battlegrounds" }, { "raid", "In raids" } } },
		{ key = "bulkBuy", kind = "bool", default = false, label = "Buy in bulk",
			tip = "Shift-click an item at a merchant: beside the game's box, Stack buys a full stack and Most as many as your gold, the merchant's stock and your bags allow, a stack at a time. Both ask first, and the game's box stays open. Not for items bought with tokens." },
		{ key = "confirmTokens", kind = "bool", default = false, label = "Buy with tokens without asking",
			tip = "Answers Yes when the game asks before it takes items or currency for a purchase. One that also costs 150 gold or more is left to you." },
		{ key = "confirmTradeable", kind = "bool", default = false, label = "Sell loot still tradeable without asking",
			tip = "Answers Okay when the game asks before you sell an item you could still trade to your group." },
		{ section = "Loot and trainers" },
		{ key = "quickLoot", kind = "bool", default = true, label = "Quick loot",
			tip = "When the game loots by itself (Auto Loot, or its key held), every slot is taken at once. Rolls still ask." },
		{ key = "makeRoom", kind = "bool", default = true, label = "Make room in full bags",
			tip = "A button under the loot window deletes the cheapest grey item while every bag is full. It names the item first, as Delete Broken Fang x3." },
		{ key = "trainAll", kind = "bool", default = true, label = "Train all button",
			tip = "On the trainer window: learns everything the trainer offers that you can pay for, and says how many, as Train all (4). A profession is left to Train, which asks first. /flatui train does the same." },
	},
	{
		key = "errandsPopups", label = "Popups and invites", parent = "errands", owner = "errands",
		{ section = "Death and popups" },
		{ key = "releaseGuard", kind = "choice", default = "instances", label = "Hold a key to release",
			tip = "Release Spirit is covered until you hold the key, so a stray click does not send you to the graveyard. The game's own timer still releases you.",
			choices = { { "off", "Off" }, { "instances", "In dungeons and raids" }, { "always", "Everywhere" } } },
		{ key = "releaseKey", kind = "choice", default = "shift", label = "Key to hold", needs = "releaseGuard", needsIn = { "instances", "always" },
			choices = { { "shift", "Shift" }, { "ctrl", "Ctrl" }, { "alt", "Alt" } } },
		{ key = "releaseBattleground", kind = "bool", default = false, label = "Release at once in battlegrounds",
			tip = "Half a second after you die in a battleground your spirit goes to the graveyard, in time for the spirit healer's next wave, and chat says so. Not while a soulstone, Reincarnation or another way back is offered, and never in an arena, the open world or a dungeon. Hold a key to release does not hold it back." },
		{ key = "summons", kind = "bool", default = false, label = "Accept summons", tip = "When the game would let you take it: not in a fight, and not on a flight path." },
		{ key = "resurrect", kind = "bool", default = true, label = "Accept resurrections", tip = "Not while the one who offers it is in combat or dead, and only once the game lets you after recent deaths." },
		{ key = "deleteWord", kind = "bool", default = true, label = "Type DELETE for you",
			tip = "Writes the word the game asks for before it deletes a good item. You still click Yes." },
		{ section = "Other players" },
		{ key = "invites", kind = "choice", default = "both", label = "Accept group invites from",
			tip = "Battle.net friends count as friends. An invite that comes in a fight is accepted when the fight ends. One that asks for roles, or would take you out of a queue, is left to you.",
			choices = { { "off", "Nobody" }, { "friends", "Friends" }, { "guild", "Your guild" }, { "both", "Friends and your guild" } } },
		{ key = "declineDuels", kind = "bool", default = false, label = "Decline duels", tip = "Every duel request is declined at once, also in a fight." },
		{ key = "mailRecipient", kind = "bool", default = true, label = "Remember the last mail recipient",
			tip = "After a letter goes, the To box keeps the name until the mailbox closes." },
	},
	{
		key = "errandsLevelling", label = "Quests and levelling", parent = "errands", owner = "errands",
		{ section = "Quests" },
		{ key = "questAccept", kind = "bool", default = true, label = "Accept quests",
			tip = "When an NPC offers one, or your group shares one. A quest that would flag you for PvP, and an escort a group member starts, still ask you." },
		{ key = "questTurnIn", kind = "bool", default = true, label = "Hand in finished quests",
			tip = "Takes the reward when there is only one; with a choice, the window stays open for you. A quest that takes money, or an item of green quality or better, is left to you." },
		{ key = "rewardValue", kind = "bool", default = true, label = "Mark the reward worth most",
			tip = "With a choice of rewards, a small gold coin on the item's icon marks the one a merchant pays most for as the window opens, and its tooltip says how much. You still choose." },
		{ key = "questLow", kind = "bool", default = false, label = "Low-level quests too", needs = "questAccept",
			tip = "Off: a grey quest is left to you, so the places in your quest log go to quests worth the time." },
		{ key = "questRepeat", kind = "bool", default = false, label = "Repeatable quests too",
			tip = "Off: a quest you can do again and again, such as a cloth or reputation hand-in, is left to you, so nothing you may want to keep is given away." },
		{ key = "questKey", kind = "choice", default = "shift", label = "Key to do it yourself",
			tip = "Hold it as you talk to an NPC, and that NPC's quests and gossip are left to you until you walk away.",
			choices = { { "shift", "Shift" }, { "ctrl", "Ctrl" }, { "alt", "Alt" } } },
		{ key = "questNpcs", kind = "list", default = 0, label = "Skipped NPCs", none = "Choose one to stop skipping", items = "QuestSkippedLines",
			pick = "QuestSkippedPick", tip = "Their quests and gossip are always left to you. /flatui npc skips the NPC you talk to or target." },
		{ section = "Gossip" },
		{ key = "gossip", kind = "choice", default = "all", label = "Gossip options",
			tip = "Saved options are picked everywhere. In the open world, the one option marked (Quest), or an NPC's only option when it has no quest for you, is picked too. An option that casts a spell is never picked.",
			choices = { { "off", "Off" }, { "saved", "Saved options only" }, { "all", "Saved, quest and only options" } } },
		{ key = "gossipSaved", kind = "list", default = 0, label = "Saved gossip options", none = "Choose one to forget", items = "GossipSavedLines",
			pick = "GossipSavedPick", tip = "/flatui gossip lists the options of the NPC you talk to, and /flatui gossip 2 saves the second one." },
		{ section = "Spell ranks" },
		{ key = "uprank", kind = "bool", default = true, label = "Put new ranks on your bars",
			tip = "After training, a line at the top of the screen offers it. Its button reloads the interface in the same click, which keeps the game's bars clean. Macros, items, the ranks you keep and a lower rank beside a higher one of the same spell stay as they are." },
		{ key = "keepRank", kind = "list", default = 0, label = "Keep a rank on your bars", none = "Choose a spell", items = "ErrandsRankCandidates", pick = "ErrandsRankKeep",
			needs = "uprank", tip = "That rank stays where it is. The other ranks of the spell are still replaced. /flatui rank and a spell link does the same." },
		{ key = "unkeepRank", kind = "list", default = 0, label = "Stop keeping a rank", none = "Choose a spell", items = "ErrandsRanksKept", pick = "ErrandsRankUnkeep", needs = "uprank" },
		{ key = "uprankNow", kind = "list", default = 0, label = "Uprank your bars now", none = "Choose", items = "ErrandsUprankLines", pick = "ErrandsUprankNow",
			needs = "uprank", tip = "Shows the line and its button now. /flatui uprank does the same." },
		{ key = "learnedLines", kind = "choice", default = "summary", label = "Lines about learned spells",
			tip = "The game's lines that start with You have learned or You have unlearned. One line in their place names what was learned, a moment after the last; with Say what was done off, the game's lines stay.",
			choices = { { "game", "As the game has it" }, { "hide", "Hidden" }, { "summary", "One line in their place" } } },
		{ section = "Reputation and talents" },
		{ key = "repFollow", kind = "bool", default = true, label = "Show the reputation you gain",
			tip = "Flat UI's experience bar shows the faction you last gained reputation with. Exalted and inactive factions are passed over, and a faction you pick in the game's reputation window shows until your next gain. The faction the game watches is not changed." },
		{ key = "talentReminder", kind = "bool", default = true, label = "Remind you of talent points",
			tip = "When you reach a level, or log in, with talent points to spend, a line in chat says how many, also with Say what was done off. A level reached in a fight is told when it ends." },
		{ section = "Waypoints" },
		{ key = "wayCommand", kind = "bool", default = true, label = "Add the /way command",
			tip = "/way 45 61 puts a pin on your map there and the game points you to it. /way Elwynn Forest 45 61, /way #1429 45 61 and /way clear work too. When another addon has /way it keeps it, and /flatui way does the same." },
		{ key = "wayArrive", kind = "bool", default = true, label = "Clear a waypoint as you reach it", needs = "wayCommand",
			tip = "A pin /way set comes off as you arrive, with a chime and a line in chat. It needs In-game navigation, which tells Flat UI you are there. A pin you put on the map yourself stays." },
		{ key = "navigation", kind = "bool", default = true, label = "In-game navigation", changed = "ErrandsNavigationChanged",
			tip = "A marker over the quest or map pin you track, with its distance, and an arrow at the edge of the screen while it is out of view, as the game's own option shows it in later expansions. Sets a game setting that Forever's options do not show. Turned off with /console showInGameNavigation 0, it stays off until you change this row. Turned off here, the game's own value is back." },
	},
	{
		key = "consumables", label = "Drink and health macros",
		{ key = "enabled", kind = "bool", default = true, label = "Keep drink and health macros",
			tip = "Two macros in your account's macro list, Flat UI Drink and Flat UI Health, written again out of combat when your bags or your level change. Put a macro on your cursor hands one to you for an action bar. Turned off, they are deleted, but one still on a bar stays until you drag it off." },
		{ key = "say", kind = "bool", default = true, label = "Say when a macro changes",
			tip = "A line in chat when a macro moves to a better drink, food, potion or healthstone, or has none left. Not at login, and not for a row you change here. Also once when you are down to 5 drinks, or 5 foods while Flat UI Health eats, and again after you restock above 5." },
		{ key = "pickup", kind = "list", default = 0, label = "Put a macro on your cursor", none = "Choose a macro", items = "ConsumablesPickupLines", pick = "ConsumablesPickup",
			tip = "Picks up Flat UI Drink or Flat UI Health, so a click on an action button puts it there. Out of a fight. The game's macro window (/macro) has them too." },
		{ section = "Drink" },
		{ key = "drink", kind = "bool", default = true, label = "Drink macro",
			tip = "Flat UI Drink drinks the best drink in your bags that your level allows, conjured water first. A character without mana leaves it as it is." },
		{ key = "manaPotion", kind = "bool", default = true, label = "Mana potion in a fight", needs = "drink",
			tip = "In a fight, where you cannot drink, Flat UI Drink takes your best mana potion." },
		{ key = "manaGem", kind = "bool", default = true, label = "Mana gem first in a fight", needs = "drink",
			tip = "For a mage: in a fight Flat UI Drink takes your best mana gem, then your best mana potion at the next press, and starts with the gem again after the fight. A gem still cooling waits behind a potion that is ready." },
		{ section = "Health" },
		{ key = "health", kind = "bool", default = true, label = "Health macro",
			tip = "Flat UI Health takes a healthstone, then at the next press your best healing potion, and starts with the healthstone again after the fight." },
		{ key = "food", kind = "bool", default = true, label = "Eat out of combat", needs = "health",
			tip = "Out of combat Flat UI Health eats the best food in your bags that your level allows, conjured food first." },
	},
	{
		key = "consumebar", label = "Consumables bar",
		{ key = "enabled", kind = "bool", default = false, label = "Show the consumables bar",
			tip = "A bar of buttons for your consumables: a click uses the item from whichever bag holds it, also in a fight. Each shows how many you carry, its cooldown and its tooltip. The first six have keys under Flat UI in the game's Key Bindings. /flatui move places it." },
		{ section = "Buttons" },
		{ key = "which", kind = "choice", default = "bags", label = "Buttons",
			tip = "Every consumable in your bags: one button for each item, never from the bank, in the order of the Bags page at Each kind, then by name; Kinds in your bags leaves kinds out. Your list: only the items you chose, in your order. Your list, then the rest: your list first, then the other consumables of your bags.",
			choices = { { "bags", "Every consumable in your bags" }, { "list", "Your list" }, { "both", "Your list, then the rest" } } },
		{ key = "empty", kind = "choice", default = "dim", label = "An item of your list with none left", needs = "which", needsIn = { "list", "both" },
			tip = "It stays on the bar, so its button keeps its place. A click on it says in chat that your bags hold none.",
			choices = { { "dim", "Show it greyed with 0" }, { "hide", "Leave a gap" } } },
		{ key = "count", kind = "bool", default = true, label = "Show count",
			tip = "How many you carry across your bags. A stack of one shows no number, but on a button of your list; none shows a red 0." },
		{ section = "Your list" },
		{ key = "add", kind = "list", default = 0, label = "Add an item", none = "Choose an item", items = "ConsumeBarCandidates", pick = "ConsumeBarAdd",
			tip = "The consumables in your bags that are not on your list, then the other items there with a use that you cannot wear, such as the Hearthstone. Or drop one on the bar out of a fight: on a button of your list it goes in that place, and while Buttons shows your list, a + at the end of the bar takes the item you hold. At most 24, kept for this character." },
		{ key = "remove", kind = "list", default = 0, label = "Take an item off", none = "Choose an item", items = "ConsumeBarListed", pick = "ConsumeBarRemove",
			tip = "Shift+right-click on its button does the same. Shift+right-click on another button puts it on your list." },
		{ key = "left", kind = "list", default = 0, label = "Move an item left", none = "Choose an item", items = "ConsumeBarListed", pick = "ConsumeBarLeft",
			tip = "One place earlier on the bar: further left while it grows right." },
		{ key = "right", kind = "list", default = 0, label = "Move an item right", none = "Choose an item", items = "ConsumeBarListed", pick = "ConsumeBarRight",
			tip = "One place later on the bar." },
		{ section = "Kinds in your bags", chips = true },
		{ key = "kindFood", kind = "bool", default = true, label = "Food and drink" },
		{ key = "kindPotion", kind = "bool", default = true, label = "Potions" },
		{ key = "kindElixir", kind = "bool", default = true, label = "Elixirs and flasks" },
		{ key = "kindScroll", kind = "bool", default = true, label = "Scrolls" },
		{ key = "kindBandage", kind = "bool", default = true, label = "Bandages" },
		{ key = "kindEnhance", kind = "bool", default = true, label = "Enhancements", tip = "Oils, sharpening stones, weightstones and the like." },
		{ key = "kindExplosive", kind = "bool", default = true, label = "Explosives and devices" },
		{ key = "kindOther", kind = "bool", default = true, label = "Other consumables", tip = "Healthstones, mana gems and the rest. They come first on the bar." },
		{ section = "Layout" },
		{ key = "size", kind = "number", default = 36, min = 20, max = 64, step = 2, unit = " px", label = "Button size" },
		{ key = "perRow", kind = "number", default = 12, min = 1, max = 24, step = 1, label = "Buttons per row", tip = "Per column while the bar grows up or down." },
		{ key = "spacing", kind = "number", default = 2, min = 0, max = 12, step = 1, unit = " px", label = "Spacing" },
		{ key = "grow", kind = "choice", default = "right", label = "Grow",
			tip = "Which way the buttons go from the corner of the bar's box in /flatui move. Rows stack upward while it grows right or left; columns go right while it grows up or down.",
			choices = { { "right", "Right" }, { "left", "Left" }, { "up", "Up" }, { "down", "Down" } } },
		{ key = "fade", kind = "bool", default = false, label = "Fade out of a fight",
			tip = "Out of a fight the buttons stay at Faded opacity, full while the mouse is over the bar, also in the gaps between buttons, in a fight and while /flatui move or Edit Mode is open. They ease up in a tenth of a second and settle back over 0.3 s, and still take clicks and keys." },
		{ key = "fadeAlpha", kind = "number", default = 40, min = 0, max = 90, step = 5, unit = "%", label = "Faded opacity", needs = "fade" },
