		{ key = "tooltips", kind = "bool", default = true, label = "Tooltips",
			tip = "Off: Gold and Frame rate let clicks through; the slots a click does something on (Bag space, Equipment set, Hearthstone, Time, Coordinates, Zone, Quest log, Experience, Reputation, Friends, Guild, Durability) and another addon's feed keep their own clicks. Right-click a slot (Alt-right-click on another addon's feed) to choose what it shows, from a menu under it whose last line opens this page; Move left and Move right there swap it with the next shown slot, and while the panel has a slot set to None, Add a slot puts a new one right beside it." },
		{ key = "outline", kind = "choice", default = "none", label = "Text outline", tip = "An outline makes a slot a little wider.",
